head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > focusMode]<br/>GridView 컴포넌트의 Body 또는 Footer 영역 선택 시 포커스 되는 형식을 설정합니다.",
    "validation" : [
        "useCtrlKey, useShiftKey, ctrlShiftKey 속성에 의한 다중 선택 동작은 focusMode='row' 이면 Row 단위 범위 선택으로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - con_focusMode / con_useCtrlKey / con_useShiftKey / con_ctrlShiftKey 콤보 값을 반영하여 GridView 동적 생성
//  - selectedCellColor(red) / selectedRowColor(blue) 를 서로 다른 색으로 지정하여
//    focusMode 에 따라 다중/범위 선택 결과가 Cell 단위(red)인지 Row 단위(blue)인지 색으로 구분
//  - 다중/범위 선택은 사용자 Ctrl+클릭 / Shift+클릭 으로 수행 (별도 확인 버튼 없음)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    //  - focusMode : 일반 선택 콤보이므로 getValue() 사용
    //  - useCtrlKey/useShiftKey/ctrlShiftKey : gdl_boolean 바인딩 콤보의 value 는 1/2/3 이므로
    //    실제 'true'/'false' 문자열은 getText() 로 읽어야 함 (빈 항목은 '' → 미설정)
    let properties = {
        focusMode        : con_focusMode.getValue(),
        useCtrlKey       : con_useCtrlKey.getText(),
        useShiftKey      : con_useShiftKey.getText(),
        ctrlShiftKey     : con_ctrlShiftKey.getText(),
        selectedCellColor: "red",
        selectedRowColor : "blue"
    };
    let cList = $c.gcm.createCList(properties);

    // 셀 클릭(Ctrl/Shift 포함) 시 다중/범위 선택 결과를 출력하기 위해 oncellclick 이벤트 등록
    let eList = $c.gcm.createEList(["oncellclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblMode  = (properties.focusMode === '') ? '미설정(기본값 cell)' : properties.focusMode;
    let lblCtrl  = (properties.useCtrlKey === '') ? '미설정(기본값 true)' : properties.useCtrlKey;
    let lblShift = (properties.useShiftKey === '') ? '미설정(기본값 false)' : properties.useShiftKey;
    let lblCS    = (properties.ctrlShiftKey === '') ? '미설정(기본값 false)' : properties.ctrlShiftKey;
    $c.gcm.createLabel('label="focusMode=' + lblMode + ' / useCtrlKey=' + lblCtrl + ' / useShiftKey=' + lblShift + ' / ctrlShiftKey=' + lblCS + ' (selectedCellColor=red, selectedRowColor=blue)"', '', 'label1');

    // dataList 생성 (여러 Row)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (4컬럼 Body 그리드)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="focusMode 다중/범위 선택 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 사용자가 Cell 을 Ctrl+클릭(다중 개별 선택) 또는 Shift+클릭(범위 선택) 했을 때 발생.
//  - getAllFocusedIndex() 로 현재 선택된 모든 Cell/Row 인덱스를 수집하여 출력
//  - focusMode='row' 이면 동일 Row 의 모든 Cell 이 선택되어 Row 단위 범위 선택으로 동작
//  - focusMode='cell'(기본) 이면 클릭/범위에 해당하는 Cell 단위로만 선택
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let mode = target1.options.focusMode;
    let effectMode = (mode === '') ? 'cell' : mode;

    // 현재 선택된 모든 셀 인덱스 (다중/범위 선택 결과)
    let all = target1.getAllFocusedIndex();

    // 선택된 셀 좌표 문자열 + 선택된 Row 집합 계산
    let cellStr = [];
    let rowSet = {};
    for (let i = 0; i < all.length; i++) {
        cellStr.push("(" + all[i].row + "," + all[i].col + ")");
        rowSet[all[i].row] = true;
    }
    let rows = Object.keys(rowSet).join(",");

    bottom.setReturnValue("[focusMode] " + effectMode + " / 마지막 클릭 Cell(" + rowIndex + "," + columnIndex + ")");
    bottom.setReturnValue("[getAllFocusedIndex 선택 Cell 수] " + all.length + " / 선택 Cell 목록 " + cellStr.join(" "));
    bottom.setReturnValue("[선택된 Row 집합] " + rows + (effectMode === 'row' ? " (Row 단위 범위 선택)" : " (Cell 단위 선택)"));
}
